import { MakeLogicType, connect, kea, path, selectors } from 'kea'

import { superpowersLogic } from 'lib/components/Superpowers/superpowersLogic'
import { capitalizeFirstLetter } from 'lib/utils/strings'

import type { FakeStatusOverride } from '../Superpowers/superpowersLogic'
import type { NormalizedStatus } from './incidentStatus'
import { incidentStatusLogic } from './incidentStatusLogic'

export type InsightsStatusType = 'operational' | 'degraded_performance' | 'partial_outage' | 'major_outage'
export type InsightsStatusBadgeStatus = 'success' | 'warning' | 'danger'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface insightsStatusLogicValues {
    status: NormalizedStatus // incidentStatusLogic
    statusDescription: string | null // incidentStatusLogic
    statusPageUrl: string // incidentStatusLogic
    fakeStatusOverride: FakeStatusOverride // superpowersLogic
    superpowersEnabled: boolean | undefined // superpowersLogic
    isFakeStatus: boolean
    insightsStatus: InsightsStatusType
    insightsStatusBadgeContent: string
    insightsStatusBadgeStatus: InsightsStatusBadgeStatus
    insightsStatusTooltip: string | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface insightsStatusLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        insightsStatus: (status: NormalizedStatus) => InsightsStatusType
        isFakeStatus: (superpowersEnabled: boolean | undefined, fakeStatusOverride: FakeStatusOverride) => boolean
        insightsStatusTooltip: (
            statusDescription: string | null,
            isFakeStatus: boolean,
            insightsStatus: InsightsStatusType
        ) => string | null
        insightsStatusBadgeContent: (insightsStatus: InsightsStatusType) => string
        insightsStatusBadgeStatus: (insightsStatus: InsightsStatusType) => InsightsStatusBadgeStatus
    }
}

export type insightsStatusLogicType = MakeLogicType<
    insightsStatusLogicValues,
    {},
    Record<string, any>,
    insightsStatusLogicMeta
>

export const insightsStatusLogic = kea<insightsStatusLogicType>([
    path(['lib', 'components', 'HelpMenu', 'insightsStatusLogic']),
    connect({
        values: [
            incidentStatusLogic,
            ['status', 'statusDescription', 'statusPageUrl'],
            superpowersLogic,
            ['fakeStatusOverride', 'superpowersEnabled'],
        ],
    }),
    selectors({
        insightsStatus: [
            (s) => [s.status],
            (status: import('./incidentStatus').NormalizedStatus): InsightsStatusType => status,
        ],
        isFakeStatus: [
            (s) => [s.superpowersEnabled, s.fakeStatusOverride],
            (
                superpowersEnabled: boolean | undefined,
                fakeStatusOverride: import('lib/components/Superpowers/superpowersLogic').FakeStatusOverride
            ): boolean => !!superpowersEnabled && fakeStatusOverride !== 'none',
        ],
        insightsStatusTooltip: [
            (s) => [s.statusDescription, s.isFakeStatus, s.insightsStatus],
            (
                statusDescription: string | null,
                isFakeStatus: boolean,
                insightsStatus: InsightsStatusType
            ): string | null => {
                if (isFakeStatus) {
                    return `[DRILL] ${capitalizeFirstLetter(insightsStatus.replace(/_/g, ' '))}`
                }
                return statusDescription
            },
        ],
        insightsStatusBadgeContent: [
            (s) => [s.insightsStatus],
            (insightsStatus: InsightsStatusType): string => (insightsStatus !== 'operational' ? '!' : '✓'),
        ],
        insightsStatusBadgeStatus: [
            (s) => [s.insightsStatus],
            (insightsStatus: InsightsStatusType): InsightsStatusBadgeStatus => {
                if (insightsStatus.includes('outage')) {
                    return 'danger'
                }
                if (insightsStatus.includes('degraded') || insightsStatus.includes('monitoring')) {
                    return 'warning'
                }
                return 'success'
            },
        ],
    }),
])
